mapper.update:
UPDATE receipt
receipt_date = #{receiptDate}, amount = #{amount}, allocated_amount = #{allocatedAmount}, unallocated_amount = #{unallocatedAmount}, remark = #{remark}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT r.*, c.customer_name
FROM receipt r
LEFT JOIN customer c ON r.customer_id = c.id

    AND r.company_id = #{companyId}
    AND r.customer_id = #{customerId}
    AND r.order_id = #{orderId}

ORDER BY r.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM receipt

    AND company_id = #{companyId}
    AND customer_id = #{customerId}
    AND order_id = #{orderId}
